files.template:
{
  "name": "{{meta:name}}",
  "author": "HIA Theme Builder",
  "variables": {
    "hia-primary": "{{token:primary.500}}",
    "hia-primary-bg": "{{token:primary.950}}",
    "hia-primary-text": "{{token:primary.100}}",
    "hia-secondary": "{{token:secondary.500}}"
  },
  "globals": {
    "background": "var(hia-primary-bg)",
    "foreground": "var(hia-primary-text)",
    "caret": "color(var(hia-primary-text) alpha(0.9))",
    "selection": "color(var(hia-primary) alpha(0.35))",
    "line_highlight": "color(var(hia-primary-text) alpha(0.06))"
  },
  "rules": [
    {
      "name": "Comment",
      "scope": "comment",
      "foreground": "var(hia-secondary-500)",
      "font_style": "italic"
    },
    {
      "name": "String",
      "scope": "string",
      "foreground": "var(hia-success-500)"
    },
    {
      "name": "Number",
      "scope": "constant.numeric",
      "foreground": "var(hia-warning-500)"
    },
    {
      "name": "Constant",
      "scope": "constant.language",
      "foreground": "var(hia-warning-600)"
    },
    {
      "name": "Keyword",
      "scope": "keyword",
      "foreground": "var(hia-primary-600)"
    },
    {
      "name": "Storage",
      "scope": "storage.type",
      "foreground": "var(hia-primary-700)"
    },
    {
      "name": "Variable",
      "scope": "variable.other",
      "foreground": "var(hia-primary-900)"
    },
    {
      "name": "Function name",
      "scope": "entity.name.function",
      "foreground": "var(hia-primary-700)"
    },
    {
      "name": "Class name",
      "scope": "entity.name.class",
      "foreground": "var(hia-secondary-700)"
    },
    {
      "name": "Tag",
      "scope": "entity.name.tag",
      "foreground": "var(hia-primary-700)"
    },
    {
      "name": "Attribute",
      "scope": "entity.other.attribute-name",
      "foreground": "var(hia-secondary-600)"
    },
    {
      "name": "Punctuation",
      "scope": "punctuation.definition",
      "foreground": "var(hia-primary-500)"
    },
    {
      "name": "Operator",
      "scope": "keyword.operator",
      "foreground": "var(hia-secondary-600)"
    },
    {
      "name": "Invalid",
      "scope": "invalid",
      "foreground": "var(hia-danger-600)"
    }
  ]
}
